//! Telemetry-only scheduling lives in the destination's existing progress ledger.
//! Bodies are regenerated by the ordinary evidence chunk, never kept in an outbox.
use super::*;
use crate::claude_local_otel::{self as otel, TelemetryGeneration};
use time::{format_description::well_known::Rfc3339, OffsetDateTime};

pub(super) const CONTRACT: &str = "claude_otel_only_sessions:v1";
#[derive(Clone, Copy)]
pub(super) struct Window {
    floor: i128,
    ceiling: Option<i128>,
    start: i128,
}
fn clock(value: &str) -> Option<i128> {
    OffsetDateTime::parse(value, &Rfc3339)
        .ok()
        .map(|t| t.unix_timestamp_nanos())
}
const SLACK: i128 = 300_000_000_000;
pub(super) fn advertised(hint: &crate::snapshot_client::ActivityHintResponse) -> Option<Window> {
    if hint.source != "claude_code"
        || !hint.local_usage_reconciliation_enabled
        || !hint.snapshot_head_cas_required
        || hint.claude_otel_only_sessions_contract.as_deref() != Some(CONTRACT)
    {
        return None;
    }
    let floor = clock(hint.claude_otel_only_pairing_floor.as_deref()?)?;
    let ceiling = match hint.claude_otel_only_pairing_ceiling.as_deref() {
        Some(value) => Some(clock(value)?),
        None => None,
    };
    if ceiling.is_some_and(|end| end <= floor + 2 * SLACK) {
        return None;
    }
    Some(Window {
        floor,
        ceiling,
        start: floor + SLACK,
    })
}
#[derive(Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub(super) struct Ledger {
    floor: i128,
    start: i128,
    #[serde(default)]
    candidates: BTreeMap<String, Candidate>,
}
#[derive(Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
struct Candidate {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    built: Option<Built>,
    #[serde(skip)]
    reading: Option<TelemetryGeneration>,
}
#[derive(Clone, PartialEq, Eq, Serialize, Deserialize)]
struct Built {
    fingerprint: String,
    body: String,
    generation: TelemetryGeneration,
}
impl std::fmt::Debug for Ledger {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("TelemetryCandidates")
            .field("count", &self.candidates.len())
            .finish()
    }
}
crate::heap_layout_bound::fields!(Ledger; floor, start, candidates);
crate::heap_layout_bound::fields!(Candidate; built, reading);
crate::heap_layout_bound::fields!(Built; fingerprint, body, generation);

impl Ledger {
    pub(super) fn settle(&mut self, root: &str) {
        self.candidates.remove(root);
    }
    pub(super) fn references(&self) -> impl Iterator<Item = &str> {
        self.candidates
            .values()
            .filter_map(|c| c.built.as_ref())
            .map(|b| b.fingerprint.as_str())
    }
}

impl SnapshotUploadProgress {
    /// Shared across the whole ACK-retirement owner, including capacity and recovery.
    pub(super) fn ack_incidence<'a>(
        &'a self,
        index: &'a ScanIndex,
    ) -> impl Iterator<Item = &'a str> {
        index.upload_progress_ack_incidence().chain(
            self.telemetry_only
                .iter()
                .flat_map(|ledger| ledger.references()),
        )
    }

    pub(super) fn seed_telemetry(
        &mut self,
        support: &Path,
        hint: &crate::snapshot_client::ActivityHintResponse,
        scan: &mut SourceScanResult,
        index: &ScanIndex,
        progress_path: &Path,
    ) -> Result<Option<Window>> {
        let Some(mut window) = advertised(hint) else {
            otel::telemetry_notices::configure(support, false)?;
            return Ok(None);
        };
        let fresh = self
            .telemetry_only
            .as_ref()
            .is_none_or(|ledger| ledger.floor != window.floor);
        if fresh {
            let ledger = self.telemetry_only.get_or_insert_with(Default::default);
            ledger.floor = window.floor;
            ledger.start = OffsetDateTime::now_utc()
                .unix_timestamp_nanos()
                .max(window.start);
            self.save(progress_path)?;
        }
        otel::telemetry_notices::configure(support, true)?;
        let pending = otel::telemetry_notices::pending(support)?;
        if !pending.is_empty() {
            let ledger = self.telemetry_only.as_mut().expect("activated ledger");
            for root in &pending {
                ledger.candidates.entry(root.clone()).or_default();
            }
            self.save(progress_path)?;
        }
        otel::telemetry_notices::forget(support, &pending)?;
        // Page facts are captured before any synthetic slot exists. An all-copy
        // page still has a transcript, even when later normalization emits none.
        let page_roots = claude_evidence_session_ids(&scan.snapshots)
            .into_iter()
            .collect::<BTreeSet<_>>();
        let accepted = &self.accepted_body_witnesses;
        let contexts = &self.accepted_body_contexts;
        let resend = &self.context_resend;
        let ledger = self.telemetry_only.as_mut().expect("activated ledger");
        window.start = ledger.start;
        let candidates = ledger.candidates.keys().cloned().collect();
        let (absent, backed) =
            crate::snapshots::claude_request_money::e2::telemetry_scope(index, &candidates);
        ledger
            .candidates
            .retain(|root, _| !page_roots.contains(root) && !backed.contains(root));
        for (root, candidate) in &mut ledger.candidates {
            if !absent.contains(root) {
                continue;
            }
            let Ok(generation) = otel::telemetry_generation(support, root) else {
                continue;
            };
            if (generation.api.is_none() || generation.trace.is_none())
                || candidate.built.as_ref().is_some_and(|built| {
                    !otel::telemetry_not_truncated(&generation, &built.generation)
                })
                || candidate.built.as_ref().is_some_and(|built| {
                    built.generation == generation
                        && accepted.get(&built.fingerprint) == Some(&built.body)
                        && !resend.requires_resend(&built.fingerprint, contexts)
                })
            {
                continue;
            }
            candidate.reading = Some(generation);
            scan.snapshots.push(SnapshotItem::neutral_telemetry(
                root.clone(),
                current_rfc3339(),
            ));
        }
        Ok(Some(window))
    }

    /// Called after ordinary policy/finalization, before upload. The generations
    /// captured before strict decode must still match; no ACK-time stat mints proof.
    pub(super) fn bind_telemetry_bodies(&mut self, support: &Path, items: &mut Vec<SnapshotItem>) {
        let Some(ledger) = self.telemetry_only.as_mut() else {
            return;
        };
        items.retain(|item| {
            if item.evidence_basis != Some("otel_only") {
                return true;
            }
            let Some(candidate) = ledger.candidates.get_mut(&item.source_session_id) else {
                return false;
            };
            let Some(generation) = candidate.reading.take() else {
                return false;
            };
            if otel::telemetry_generation(support, &item.source_session_id)
                .ok()
                .as_ref()
                != Some(&generation)
            {
                return false;
            }
            candidate.built = Some(Built {
                fingerprint: item.snapshot_fingerprint.clone(),
                body: snapshot_upload_body_witness(item),
                generation,
            });
            true
        });
    }

    pub(super) fn settle_telemetry_root(&mut self, root: &str) {
        if let Some(ledger) = self.telemetry_only.as_mut() {
            ledger.candidates.remove(root);
        }
    }
}

/// Called inside the ordinary evidence chunk with its already-strict loaded rows.
pub(super) fn build(
    mut item: SnapshotItem,
    api: &otel::ClaudeLocalOtelLoadReport,
    trace: &otel::ClaudeTraceOwnershipLoadReport,
    index: &ScanIndex,
    window: Window,
    accepted: Option<&crate::snapshots::claude_request_identity::AcceptedBuckets>,
    budget: crate::snapshots::claude_request_identity::WireBudget<'_>,
) -> Result<Option<SnapshotItem>, ()> {
    use crate::snapshots::{
        claude_request_census, claude_request_identity, claude_request_money::e2,
    };
    let root = item.source_session_id.as_str();
    // The caller already proved a healthy strict read, including empty files.
    let rows = api.evidence.get(root).map(Vec::as_slice).unwrap_or(&[]);
    let mut unique = BTreeMap::new();
    for row in rows {
        if unique
            .insert(row.request_id.as_str(), row)
            .is_some_and(|old: &otel::ClaudeLocalOtelEvidence| old.fingerprint != row.fingerprint)
        {
            return Err(());
        }
    }
    let traces = trace.evidence.get(root).map(Vec::as_slice).unwrap_or(&[]);
    let trace_ids = traces
        .iter()
        .map(|row| row.request_id.as_str())
        .collect::<BTreeSet<_>>();
    if trace_ids != unique.keys().copied().collect() {
        return Err(());
    }
    if unique.is_empty() {
        return Ok(None);
    }
    if traces
        .iter()
        .any(|row| !crate::snapshots::claude_trace_evidence_fingerprint_is_valid(row))
    {
        return Err(());
    }
    let wanted = unique
        .keys()
        .map(|id| claude_request_census::claude_request_hash(id))
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let held = claude_request_census::positive_holders(index, &wanted);
    let mut entity = e2::ClaudeEntityBody::default();
    let mut first = i128::MAX;
    let mut last = i128::MIN;
    for row in unique.values() {
        let at = clock(&row.observed_at).ok_or(())?;
        // Never turn an old root's post-activation suffix into a fresh session.
        if at <= window.start || window.ceiling.is_some_and(|end| at >= end - SLACK) {
            return Ok(None); // Permanently before this pairing's admission window.
        }
        if held.contains(&claude_request_census::claude_request_hash(&row.request_id)) {
            continue;
        }
        if row.request_count != 1
            || row.session_id.as_ref() != root
            || !crate::snapshots::claude_api_evidence_fingerprint_is_valid(row)
        {
            return Err(());
        }
        e2::add_reported_row(
            &mut entity,
            row,
            claude_request_identity::side_call_account(row, root),
            None,
        )
        .ok_or(())?;
        first = first.min(at);
        last = last.max(at);
    }
    if entity.grains.is_empty() {
        return Ok(None);
    }
    entity.telemetry_owned_complete = true;
    let format = |at| {
        OffsetDateTime::from_unix_timestamp_nanos(at)
            .ok()?
            .format(&Rfc3339)
            .ok()
    };
    item.source_started_at = format(first);
    item.source_last_activity_at = format(last);
    if !e2::emit_entity(&mut item, &entity)
        || !claude_request_identity::tag_telemetry_entity(&mut item, &entity, accepted, budget)
    {
        return Err(());
    }
    Ok(Some(item))
}

